# Vehicle inventory with OOP
class Vehicle:
    def __init__(self, model, price, units):
        self.model = model
        self.price = price
        self.units = units

    def sell(self, n):
        if n > self.units:
            raise ValueError(f"Only {self.units} units of {self.model} available")
        self.units -= n

    def restock(self, n):
        self.units += n

    def value(self):
        return self.price * self.units

